head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/*
 * 증권그룹ID
 */
SECUGRP_ID_PF = 'PF'; // 공모펀드

/*
 * 업무구분코드
 */
LIST_BZ_TP_CD_810 = "810"; // PF 신규상장
LIST_BZ_TP_CD_811 = "811"; // PF 변경상장
LIST_BZ_TP_CD_812 = "812"; // PF 상장폐지
LIST_BZ_TP_CD_813 = "813"; // PF 거래정지
LIST_BZ_TP_CD_814 = "814"; // PF 원부관리
LIST_BZ_TP_CD_815 = "815"; // PF 관리종목
LIST_BZ_TP_CD_816 = "816"; // PF 투자유의
LIST_BZ_TP_CD_817 = "817"; // PF 변경상장(원부변경)
LIST_BZ_TP_CD_818 = "818"; // PF 종목명변경

/*
 * 신규상장 구분
 */
DIV_R_LISTING_EXEM_PF = '0';
DIV_R_LISTING_PF_ISU = '1';
DIV_R_LISTING_PF_CLSBZ = '2';
DIV_L_LISTING_PF_DETAIL = '3';
DIV_L_LISTING_PF_SEND = '4';

/*
 * 변경상장 구분
 */
DIV_IDX_PF_BOK_CHG = '88'; /* PF 원부변경신청 */


/*
 * 종목명 변경구분
 */
DIV_IDX_ISU_NM_PF_RECV_LIST = '0';
DIV_IDX_ISU_NM_PF_HIST_LIST = '1';
DIV_IDX_PF_BOK_RECV_LIST = '2';
DIV_IDX_ISU_NM_PF_BF_INFO = '3';
DIV_IDX_ISU_NM_PF_RECV_READ = '4';
DIV_IDX_ISU_NM_PF_HIST_READ = '5';
/*
 * 주식발행
 */
DIV_IDX_CHG_ISS_PF_RECV = '0';
DIV_IDX_CHG_ISS_PF_HIST = '1';

/**
 * 공모펀드 변경상장 동일날짜 중복조치 체크
 * @param dtsObj
 * @param gIsurCd
 * @param gChdDD
 * @param gbzProcsNo
 * @param gListBzTpCd
 * @returns {Boolean}
 */
/**
 * @method
 * @name fn_pf_check_bz_doubleinput
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} gIsurCd desc
 * @param {string} gChdDD desc
 * @param {string} gbzProcsNo desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_pf_check_bz_doubleinput = function(dtsObj, gIsurCd, gChdDD, gbzProcsNo) {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=BZ_PROCS_NO_CHECK_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.pf.select.bzprocsno.doublinputchek.condition" + "&{P}param01=" + gIsurCd + "&{P}param02=" + gChdDD + "&{P}param03=" + gbzProcsNo;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    var vPROCS_DDTM = dtsObj.getCellData(1, "DISCLS_PROCS_DDTM");
    var vPROCS_STAT_CD = dtsObj.getCellData(1, "DISCLS_PROCS_STAT_CD");
    if (vPROCS_DDTM == "") {
        return true;
    } else {
        alert("[" + vPROCS_STAT_CD + "]건으로 " + vPROCS_DDTM + "에  이미 입력되어있습니다.");
        return false;
    }
    var gCnt = dtsObj.getCellData(1, "CNT");
    if (gCnt > 0) {
        alert("변경일자가 동일한 시장안내정보가 이미 입력되었습니다");
        return false;
    } else {
        return true;
    }
};



/**
 * 상장처리상태값으로 공시여부 확인
 * @param dtsObj
 * @param gBzProcsNo
 * @returns {Boolean}
 */
/**
 * @method
 * @name fn_check_delete_discls_procsstat
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} gBzProcsNo desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_check_delete_discls_procsstat = function(dtsObj, gBzProcsNo) {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=BZ_PROCS_NO_CHECK_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.pf.select.bzprocsno.disclsstatcd" + "&{P}param01=" + gBzProcsNo;
    dtsObj.DataID = encodeURI(url);
    dtsObj.reset();
    var vPROCS_DDTM = dtsObj.getCellData(1, "DISCLS_PROCS_DDTM");
    if (vPROCS_DDTM == "") {
        return true;
    } else {
        alert("본 건의 시장안내공시가 " + vPROCS_DDTM + "에  이미 승인되어 삭제 하실 수 없습니다.");
        return false;
    }
};
